import { type VariantProps, cva } from 'class-variance-authority';
import { type ComponentProps, type ComponentRef, forwardRef } from 'react';

import { cn } from '../../../../lib/utils';
import { Button } from '../button';
import { Input } from '../input';
import { Textarea } from '../textarea';

const InputGroup = forwardRef<ComponentRef<'div'>, ComponentProps<'div'>>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        data-slot="input-group"
        role="group"
        className={cn(
          'group/input-group bg-background border-input dark:bg-input/30 relative flex w-full items-center rounded-md border shadow-sm transition-colors transition-shadow outline-none',
          'h-9 min-w-0 has-[>textarea]:h-auto',
          'has-[>[data-align=inline-start]]:[&>input]:pl-2 has-[>[data-align=inline-start]]:[&>input]:rounded-l-none has-[>[data-align=inline-start]]:[&>textarea]:rounded-l-none',
          'has-[>[data-align=inline-end]]:[&>input]:pr-2 has-[>[data-align=inline-end]]:[&>input]:rounded-r-none has-[>[data-align=inline-end]]:[&>textarea]:rounded-r-none',
          'has-[>[data-align=block-start]]:h-auto has-[>[data-align=block-start]]:flex-col has-[>[data-align=block-start]]:[&>input]:pb-3',
          'has-[>[data-align=block-end]]:h-auto has-[>[data-align=block-end]]:flex-col has-[>[data-align=block-end]]:[&>input]:pt-3',
          'has-[[data-slot=input-group-control]:focus-visible]:shadow-focus-ring has-[[data-slot=input-group-control]:focus-visible]:border-transparent',
          'has-[[data-slot=input-group-control][aria-invalid=true]]:shadow-focus-ring-destructive has-[[data-slot=input-group-control][aria-invalid=true]]:border-transparent',
          'has-[[data-slot=input-group-control]:read-only]:border-transparent has-[[data-slot=input-group-control]:read-only]:shadow-none',
          'hover:has-[[data-slot=input-group-control]:read-only]:border-transparent hover:has-[[data-slot=input-group-control]:read-only]:bg-accent hover:has-[[data-slot=input-group-control]:read-only]:text-accent-foreground',
          className
        )}
        {...props}
      />
    );
  }
);
InputGroup.displayName = 'InputGroup';

const inputGroupAddonVariants = cva(
  "text-muted-foreground flex h-auto cursor-text items-center justify-center gap-2 py-1.5 text-sm font-medium select-none [&>svg:not([class*='size-'])]:size-4 [&>kbd]:rounded-sm group-data-[disabled=true]/input-group:opacity-50",
  {
    variants: {
      align: {
        'inline-start':
          'order-first pl-3 has-[>button]:-ml-2 has-[>kbd]:-ml-1.5',
        'inline-end': 'order-last pr-3 has-[>button]:-mr-2 has-[>kbd]:-mr-1.5',
        'block-start':
          'order-first w-full justify-start px-3 pt-3 [.border-b]:pb-3 group-has-[>input]/input-group:pt-2.5',
        'block-end':
          'order-last w-full justify-start px-3 pb-3 [.border-t]:pt-3 group-has-[>input]/input-group:pb-2.5',
      },
    },
    defaultVariants: {
      align: 'inline-start',
    },
  }
);

const InputGroupAddon = forwardRef<
  HTMLDivElement,
  ComponentProps<'div'> & VariantProps<typeof inputGroupAddonVariants>
>(({ className, align = 'inline-start', ...props }, ref) => {
  return (
    <div
      ref={ref}
      role="group"
      data-slot="input-group-addon"
      data-align={align}
      className={cn(inputGroupAddonVariants({ align }), className)}
      onClick={(e) => {
        if (e.target instanceof HTMLElement && e.target.closest('button')) {
          return;
        }
        e.currentTarget.parentElement?.querySelector('input')?.focus();
      }}
      {...props}
    />
  );
});
InputGroupAddon.displayName = 'InputGroupAddon';

const inputGroupButtonVariants = cva(
  'text-sm shadow-none flex gap-2 items-center',
  {
    variants: {
      size: {
        xs: "h-6 gap-1 px-2 rounded-sm [&>svg:not([class*='size-'])]:size-3.5 has-[>svg]:px-2",
        sm: 'h-7 px-2.5 gap-1.5 rounded-md has-[>svg]:px-2.5',
        'icon-xs': 'size-6 rounded-xs p-0 has-[>svg]:p-0',
        'icon-sm': 'size-7 p-0 has-[>svg]:p-0',
      },
    },
    defaultVariants: {
      size: 'xs',
    },
  }
);

const InputGroupButton = forwardRef<
  ComponentRef<typeof Button>,
  Omit<ComponentProps<typeof Button>, 'size'> &
    VariantProps<typeof inputGroupButtonVariants>
>(
  (
    { className, type = 'button', variant = 'ghost', size = 'xs', ...props },
    ref
  ) => {
    return (
      <Button
        ref={ref}
        type={type}
        data-size={size}
        variant={variant}
        className={cn(inputGroupButtonVariants({ size }), className)}
        {...props}
      />
    );
  }
);
InputGroupButton.displayName = 'InputGroupButton';

const InputGroupText = forwardRef<HTMLSpanElement, ComponentProps<'span'>>(
  ({ className, ...props }, ref) => {
    return (
      <span
        ref={ref}
        data-slot="input-group-text"
        className={cn(
          "text-muted-foreground flex items-center gap-2 text-sm [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4",
          className
        )}
        {...props}
      />
    );
  }
);
InputGroupText.displayName = 'InputGroupText';

const InputGroupInput = forwardRef<HTMLInputElement, ComponentProps<'input'>>(
  ({ className, ...props }, ref) => {
    return (
      <Input
        ref={ref}
        data-slot="input-group-control"
        className={cn(
          'flex-1 rounded-md border-0 bg-transparent shadow-none hover:bg-transparent hover:text-current dark:bg-transparent',
          'focus-visible:shadow-none focus-visible:border-transparent',
          'aria-invalid:focus-visible:shadow-none aria-invalid:focus-visible:border-transparent',
          className
        )}
        {...props}
      />
    );
  }
);
InputGroupInput.displayName = 'InputGroupInput';

const InputGroupTextarea = forwardRef<
  HTMLTextAreaElement,
  ComponentProps<'textarea'>
>(({ className, ...props }, ref) => {
  return (
    <Textarea
      ref={ref}
      data-slot="input-group-control"
      className={cn(
        'flex-1 resize-none rounded-md border-0 bg-transparent py-3 shadow-none focus-visible:shadow-none focus-visible:border-transparent aria-invalid:focus-visible:shadow-none aria-invalid:focus-visible:border-transparent dark:bg-transparent hover:bg-transparent hover:text-current',
        className
      )}
      {...props}
    />
  );
});
InputGroupTextarea.displayName = 'InputGroupTextarea';

export {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupText,
  InputGroupInput,
  InputGroupTextarea,
};

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@100..900&family=Space+Grotesk:wght@300..700&family=Source+Code+Pro:wght@200..900&display=swap");
@import "tailwindcss";
@import "tw-animate-css";
@import "./colors.css";

@custom-variant dark (&:is(.dark *));

/* Dark mode configuration */
@variant dark (@media (prefers-color-scheme: dark));
@variant dark (.dark &);

@theme inline {
  /* Container query breakpoint overrides for layout system */
  --container-2xl: 40rem; /* 640px - Override Tailwind's default 672px */
  --container-8xl: 96rem; /* 1536px - Custom breakpoint for widest layouts */

  /* Typography scale overrides - font sizes */
  --text-2xs: 0.625rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.75rem;
  --text-4xl: 2rem;
  --text-5xl: 2.25rem;

  /* Typography scale overrides - line heights */
  --text-2xs--line-height: 0.75rem;
  --text-xs--line-height: 0.875rem;
  --text-sm--line-height: 1.125rem;
  --text-base--line-height: 1.25rem;
  --text-lg--line-height: 1.5rem;
  --text-xl--line-height: 1.5rem;
  --text-2xl--line-height: 1.75rem;
  --text-3xl--line-height: 2rem;
  --text-4xl--line-height: 2.5rem;
  --text-5xl--line-height: 2.75rem;

  --font-sans: var(--font-inter);
  --font-marketing: var(--font-space-grotesk);
  --font-mono: var(--font-source-code-pro);
  --tracking-tight: -0.04px;
  --tracking-tighter: -0.08px;
  --tracking-tightest: -0.1px;
  --shadow-sm: 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-default:
    0 1px 3px 0 var(--effect-shadow-md), 0 1px 2px 0 var(--effect-shadow-sm);
  --shadow-md:
    0 4px 6px -1px var(--effect-shadow-md),
    0 2px 4px -1px var(--effect-shadow-sm);
  --shadow-lg:
    0 10px 15px -3px var(--effect-shadow-lg),
    0 4px 6px -2px var(--effect-shadow-sm);
  --shadow-xl:
    0 20px 25px -5px var(--effect-shadow-xl),
    0 10px 10px -5px var(--effect-shadow-lg);
  --shadow-focus-ring: 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-muted);
  --shadow-focus-ring-destructive:
    0 0 0 2px var(--ring-critical), 0 0 0 4px var(--ring-critical-shadow);

  --radius-none: 0px;
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-3xl: 24px;
  --radius-4xl: 32px;
  --radius-full: 9999px;
  --avatar-icon-default: 1.09375rem;
  --avatar-icon-xs: 0.875rem;
  --avatar-icon-xxs: 0.65625rem;
  --avatar-image-backdrop: rgba(2, 6, 23, 0.2);

  /* Legacy semantic utility aliases */
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-hover: var(--secondary-hover);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-shadow: var(--ring-shadow);
  --color-ring-destructive: var(--ring-destructive);
  --color-ring-destructive-shadow: var(--ring-destructive-shadow);
  --color-destructive: var(--destructive);
  --color-destructive-hover: var(--destructive-hover);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-warning: var(--warning);
  --color-warning-hover: var(--warning-hover);
  --color-warning-foreground: var(--warning-foreground);
  --color-success: var(--success);
  --color-success-hover: var(--success-hover);
  --color-success-foreground: var(--success-foreground);
  --color-neutral: var(--neutral);
  --color-neutral-hover: var(--neutral-hover);
  --color-neutral-foreground: var(--neutral-foreground);
  --color-undefined: var(--undefined);
  --color-undefined-hover: var(--undefined-hover);
  --color-undefined-foreground: var(--undefined-foreground);
  --color-disabled: var(--disabled);
  --color-disabled-foreground: var(--disabled-foreground);
  --color-hover: var(--hover);
  --color-foreground-link: var(--foreground-link);
  --color-backdrop: var(--backdrop);
  --color-toggled: var(--toggled);
  --color-toggled-hover: var(--toggled-hover);
  --color-toggled-foreground: var(--toggled-foreground);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Additional legacy decorative aliases */
  --color-decorative-background-mountain: var(--decorative-background-mountain);
  --color-decorative-background-fjord: var(--decorative-background-fjord);
  --color-decorative-background-nordic: var(--decorative-background-nordic);
  --color-decorative-background-aurora: var(--decorative-background-aurora);
  --color-decorative-background-dusk: var(--decorative-background-dusk);
  --color-decorative-background-orange: var(--decorative-background-orange);
  --color-decorative-background-sky: var(--decorative-background-sky);
  --color-decorative-background-gray: var(--decorative-background-gray);
  --color-decorative-background-hover-mountain: var(--decorative-background-hover-mountain);
  --color-decorative-background-hover-fjord: var(--decorative-background-hover-fjord);
  --color-decorative-background-hover-nordic: var(--decorative-background-hover-nordic);
  --color-decorative-background-hover-aurora: var(--decorative-background-hover-aurora);
  --color-decorative-background-hover-dusk: var(--decorative-background-hover-dusk);
  --color-decorative-background-hover-orange: var(--decorative-background-hover-orange);
  --color-decorative-background-hover-sky: var(--decorative-background-hover-sky);
  --color-decorative-background-hover-gray: var(--decorative-background-hover-gray);
  --color-decorative-foreground-mountain: var(--decorative-foreground-mountain);
  --color-decorative-foreground-fjord: var(--decorative-foreground-fjord);
  --color-decorative-foreground-nordic: var(--decorative-foreground-nordic);
  --color-decorative-foreground-aurora: var(--decorative-foreground-aurora);
  --color-decorative-foreground-dusk: var(--decorative-foreground-dusk);
  --color-decorative-foreground-orange: var(--decorative-foreground-orange);
  --color-decorative-foreground-sky: var(--decorative-foreground-sky);
  --color-decorative-foreground-gray: var(--decorative-foreground-gray);

  --color-gradient-nordic: var(--gradient-nordic);
  --color-gradient-aurora: var(--gradient-aurora);
  --color-gradient-dusk: var(--gradient-dusk);
  --color-gradient-equinox: var(--gradient-equinox);
  --color-gradient-summer: var(--gradient-summer);
  --color-gradient-spring: var(--gradient-spring);
  --color-gradient-fall: var(--gradient-fall);

  --color-fjord: var(--fjord-50);
  --color-nordic: var(--nordic-50);
  --color-aurora: var(--aurora-50);
  --color-sky: var(--sky-50);
}

:root {
  --radius: 0.375rem;
  --font-inter: "Inter", sans-serif;
  --font-space-grotesk: "Space Grotesk", sans-serif;
  --font-source-code-pro: "Source Code Pro", monospace;
  --code-block-collapsed-height: 6.5rem;
  --code-block-fade-height: 0.9375rem;
  --message-content-max-width: 80%;
  --alert-icon-width: calc(var(--spacing) * 4);
  --drawer-max-height: 80vh;

  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-50) 0%,
    var(--nordic-400) 44%,
    var(--nordic-200) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--aurora-400) 50%,
    var(--aurora-200) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-50) 0%,
    var(--dusk-400) 48%,
    var(--dusk-200) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-600) 0%,
    var(--dusk-300) 40%,
    var(--aurora-50) 60%,
    var(--aurora-100) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-100) 0%,
    var(--dusk-50) 50%,
    var(--aurora-100) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-50) 0%,
    var(--nordic-100) 50%,
    var(--aurora-100) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-550) 0%,
    var(--dusk-550) 50%,
    var(--dusk-300) 100%
  );

  /* Legacy semantic aliases mapped to latest token model */
  --card: var(--card-background);
  --card-foreground: var(--foreground);
  --popover: var(--popover-background);
  --popover-foreground: var(--foreground);
  --primary: var(--primary-background);
  --primary-hover: var(--primary-background-hover);
  --primary-foreground: var(--foreground-on-primary);
  --secondary: var(--secondary-background);
  --secondary-hover: var(--secondary-background-hover);
  --muted: var(--muted-background);
  --accent: var(--active-muted-background);
  --accent-foreground: var(--active-foreground);
  --mountain: var(--muted-background);
  --mountain-foreground: var(--foreground);
  --foreground-link: var(--link-foreground);
  --input: var(--border);
  --ring-shadow: var(--ring-muted);
  --ring-destructive: var(--ring-critical);
  --ring-destructive-shadow: var(--ring-critical-shadow);
  --backdrop: var(--overlay-background);
  --destructive: var(--destructive-background);
  --destructive-hover: var(--destructive-background-hover);
  --warning: var(--warning-background);
  --warning-hover: var(--warning-background-hover);
  --success: var(--success-background);
  --success-hover: var(--success-background-hover);
  --neutral: var(--neutral-background);
  --neutral-hover: var(--neutral-background-hover);
  --undefined: var(--neutral-muted-background);
  --undefined-hover: var(--neutral-background-hover);
  --undefined-foreground: var(--neutral-foreground);
  --disabled: var(--disabled-background);
  --hover: var(--background-hover);
  --destructive-foreground-alternate: var(--destructive-foreground-on-critical);
  --destructive-alternative: var(--destructive-muted-background);
  --warning-foreground-alternate: var(--warning-foreground-on-warning);
  --warning-alternative: var(--warning-muted-background);
  --success-foreground-alternate: var(--success-foreground-on-success);
  --neutral-foreground-alternate: var(--neutral-foreground-on-neutral);
  --neutral-alternative: var(--neutral-muted-background);
  --undefined-alternative: var(--neutral-muted-background);
  --undefined-foreground-alternate: var(--neutral-foreground-on-neutral);
  --toggled: var(--neutral-background);
  --toggled-hover: var(--neutral-background-hover);
  --toggled-foreground: var(--foreground-on-toggled);
  --inverted: var(--background-fixed-dark);
  --inverted-foreground: var(--foreground-fixed-light);
  --inverted-foreground-muted: var(--muted-foreground-fixed-light);
  --inverted-destructive-foreground: var(--destructive-foreground);
  --inverted-success-foreground: var(--success-foreground);
  --decorative-background-mountain: var(--decorative-mountain-background);
  --decorative-background-fjord: var(--decorative-fjord-background);
  --decorative-background-nordic: var(--decorative-nordic-background);
  --decorative-background-aurora: var(--decorative-aurora-background);
  --decorative-background-dusk: var(--decorative-dusk-background);
  --decorative-background-orange: var(--decorative-orange-background);
  --decorative-background-sky: var(--decorative-sky-background);
  --decorative-background-gray: var(--decorative-mountain-background);
  --decorative-background-hover-mountain: var(--decorative-mountain-background-hover);
  --decorative-background-hover-fjord: var(--decorative-fjord-background-hover);
  --decorative-background-hover-nordic: var(--decorative-nordic-background);
  --decorative-background-hover-aurora: var(--decorative-aurora-background-hover);
  --decorative-background-hover-dusk: var(--decorative-dusk-background-hover);
  --decorative-background-hover-orange: var(--decorative-orange-background-hover);
  --decorative-background-hover-sky: var(--decorative-sky-background-hover);
  --decorative-background-hover-gray: var(--decorative-mountain-background-hover);
  --decorative-foreground-mountain: var(--decorative-mountain-foreground);
  --decorative-foreground-fjord: var(--decorative-fjord-foreground);
  --decorative-foreground-nordic: var(--decorative-nordic-foreground);
  --decorative-foreground-aurora: var(--decorative-aurora-foreground);
  --decorative-foreground-dusk: var(--decorative-dusk-foreground);
  --decorative-foreground-orange: var(--decorative-orange-foreground);
  --decorative-foreground-sky: var(--decorative-sky-foreground);
  --decorative-foreground-gray: var(--decorative-mountain-foreground);
  --sidebar: var(--mountain-900);
  --sidebar-foreground: var(--mountain-100);
  --sidebar-primary: var(--mountain-600);
  --sidebar-primary-foreground: var(--mountain-white);
  --sidebar-accent: var(--mountain-700);
  --sidebar-accent-foreground: var(--mountain-white);
  --sidebar-border: var(--mountain-800);
  --sidebar-ring: var(--gray-300);
}

.dark {
  --gradient-nordic: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--nordic-600) 44%,
    var(--nordic-800) 100%
  );
  --gradient-aurora: linear-gradient(
    -100deg,
    var(--aurora-900) 0%,
    var(--aurora-600) 50%,
    var(--aurora-800) 100%
  );
  --gradient-dusk: linear-gradient(
    -100deg,
    var(--dusk-900) 0%,
    var(--dusk-600) 48%,
    var(--dusk-800) 100%
  );
  --gradient-equinox: linear-gradient(
    -100deg,
    var(--dusk-400) 0%,
    var(--dusk-700) 40%,
    var(--aurora-950) 60%,
    var(--aurora-900) 100%
  );
  --gradient-summer: linear-gradient(
    -100deg,
    var(--nordic-900) 0%,
    var(--dusk-950) 50%,
    var(--aurora-900) 100%
  );
  --gradient-spring: linear-gradient(
    -100deg,
    var(--aurora-950) 0%,
    var(--nordic-900) 50%,
    var(--aurora-900) 100%
  );
  --gradient-fall: linear-gradient(
    -100deg,
    var(--fjord-450) 0%,
    var(--dusk-450) 50%,
    var(--dusk-700) 100%
  );
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    @apply text-undefined-foreground;
  }
}

@layer utilities {
  [data-state="closed"] {
    --tw-animation-fill-mode: forwards;
  }

  @keyframes accordion-down {
    from {
      height: 0;
    }

    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }

    to {
      height: 0;
    }
  }

  .animate-accordion-down {
    animation: accordion-down 0.2s ease-out;
  }

  .animate-accordion-up {
    animation: accordion-up 0.2s ease-out;
  }
}
